  "Fill the pot": "เติมน้ำใส่หม้อ",
  "Fill the large pot with # L cold water. Don't add oil.": "เติมน้ำเย็น # ลิตรลงในหม้อใบใหญ่ ไม่ต้องใส่น้ำมัน",
