  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "วางหม้อบนหัวเตาที่ใหญ่ที่สุด เปิดไฟ«แรง» แล้วปิดฝา (น้ำจะเดือดเร็วขึ้น)",
