  "Put the diced pancetta into the COLD pan, then turn the burner to LOW. Lean pancetta? Add 1 tsp neutral oil first. Add the lightly crushed whole garlic clove.": "ใส่แพนเชตตาที่หั่นแล้วลงในกระทะ«เย็น» แล้วเปิดไฟ«อ่อน» แพนเชตตามีมันน้อยหรือ ใส่น้ำมันพืช 1 ช้อนชาก่อน ใส่กระเทียมทั้งกลีบที่ทุบเบาๆ",
  "Put the diced pancetta into the COLD pan, then turn the burner to LOW. Lean pancetta? Add 1 tsp neutral oil first. Add the lightly crushed whole garlic clove. Let the fat melt out slowly for about 9 minutes, stirring now and then.": "ใส่แพนเชตตาที่หั่นแล้วลงในกระทะ«เย็น» แล้วเปิดไฟ«อ่อน» แพนเชตตามีมันน้อยหรือ ใส่น้ำมันพืช 1 ช้อนชาก่อน ใส่กระเทียมทั้งกลีบที่ทุบเบาๆ เจียวมันช้าๆ ประมาณ 9 นาที คนเป็นระยะ",
