  "Ladle into bowls. Top with grated cheddar, a spoon of sour cream and a few cilantro leaves. Tortillas (or rice) on the side, lime wedge optional.": "ตักใส่ชาม โรยเชดดาร์ขูด ซาวร์ครีมหนึ่งช้อน และใบผักชีเล็กน้อย เสิร์ฟกับตอร์ติญา (หรือข้าว) และมะนาวฝานถ้าชอบ",
