  "Portion semolina and sugar": "ตวงเซโมลินาและน้ำตาล",
  "Measure the semolina and the sugar (or erythritol). Per 1 dl milk: 1 tbsp semolina, ½ tbsp sugar (or ⅔ tbsp erythritol).": "ตวงเซโมลินาและน้ำตาล (หรืออีริทริทอล) ต่อนม 1 เดซิลิตร: เซโมลินา 1 ช้อนโต๊ะ น้ำตาล ½ ช้อนโต๊ะ (หรืออีริทริทอล ⅔ ช้อนโต๊ะ)",
  "Both measured": "ตวงทั้งสองอย่างแล้ว",
