  "Drain the pasta in a colander.": "เทพาสต้าลงกระชอนให้สะเด็ดน้ำ",
  "Toss in the fat": "คลุกกับน้ำมัน",
  "Tip the pasta into the pan with the bacon fat (or into the pot with the butter) and toss over low heat for a minute.": "ใส่พาสต้าลงในกระทะที่มีน้ำมันเบคอน (หรือหม้อที่มีเนย) แล้วคลุกด้วยไฟอ่อน 1 นาที",
  "Coated and hot": "เคลือบทั่วและร้อน",
  "Top and serve": "โรยหน้าแล้วเสิร์ฟ",
  "Put the pasta on warm plates. Top with the túró, a spoonful of sour cream and the crispy bacon (sprinkle with sugar if you like it sweet).": "ตักพาสต้าใส่จานอุ่น โรยหน้าด้วยทูโร ซาวร์ครีม 1 ช้อน และเบคอนกรอบ (โรยน้ำตาลถ้าชอบหวาน)",
  "Break the pasta · Crumble the túró": "หักเส้นพาสต้า · ขยี้ทูโร",
  "coarsely grated": "ขูดหยาบ",
  "Grate the squash": "ขูดสควอช",
  "Peel the squash if the skin is tough, scoop out any big seeds and grate it coarsely into a bowl.": "ปอกเปลือกสควอชถ้าเปลือกแข็ง เอาเมล็ดใหญ่ออก แล้วขูดหยาบลงในชาม",
  "Salt and wait": "ใส่เกลือแล้วรอ",
  "Mix in the salt and leave for 15 minutes so the squash lets out its water.": "คลุกเกลือแล้วพักไว้ 15 นาทีให้สควอชคายน้ำ",
  "Liquid in the bowl": "มีน้ำในชาม",
  "Chop the onion and dill": "สับหัวหอมและผักชีลาว",
  "Finely chop the onion (and the fresh dill).": "สับหัวหอม (และผักชีลาวสด) ให้ละเอียด",
  "Squeeze the squash": "บีบน้ำสควอช",
  "Squeeze the squash firmly by the handful and pour away the liquid.": "บีบสควอชทีละกำมือให้แห้งแล้วเทน้ำทิ้ง",
  "Heat the oil in the pot and cook the onion gently until glassy; do not let it brown.": "ตั้งน้ำมันในหม้อ ผัดหัวหอมเบา ๆ จนใส ระวังอย่าให้เปลี่ยนสี",
  "Squash in": "ใส่สควอช",
  "Take the pot off the heat, stir in the paprika, then add the squash, half the dill and the water.": "ยกหม้อลงจากเตา คนปาปริกาให้เข้ากัน แล้วใส่สควอช ผักชีลาวครึ่งหนึ่ง และน้ำ",
  "Squash in the pot": "สควอชอยู่ในหม้อ",
  "Cover and cook until the squash is soft but still has a little bite, stirring now and then.": "ปิดฝาแล้วต้มจนสควอชนิ่มแต่ยังกรุบเล็กน้อย คนเป็นระยะ",
  "Soft, a little bite": "นิ่ม ยังกรุบเล็กน้อย",
  "Sour cream mix": "ส่วนผสมซาวร์ครีม",
  "Whisk the sour cream and the flour smooth in a small bowl.": "ตีซาวร์ครีมกับแป้งในชามเล็กจนเนียน",
  "Stir a ladle of the hot liquid into the sour cream mix, then stir it all into the pot. Simmer 2 to 3 minutes until thick.": "ตักน้ำร้อน 1 ทัพพีคนลงในส่วนผสมซาวร์ครีม แล้วเททั้งหมดลงหม้อ เคี่ยวไฟอ่อน 2–3 นาทีจนข้น",
  "Turn off the heat. Add the vinegar, the sugar, the rest of the dill and salt to taste. It should taste gently sweet and sour.": "ปิดไฟ ใส่น้ำส้มสายชู น้ำตาล ผักชีลาวที่เหลือ และเกลือตามชอบ รสควรเปรี้ยวอมหวานเล็กน้อย",
  "Gently sweet and sour": "เปรี้ยวอมหวานเล็กน้อย",
  "Ladle into deep plates. Serve with bread, or with a fried sausage or a meat patty on top.": "ตักใส่จานลึกเสิร์ฟกับขนมปัง หรือวางไส้กรอกย่างหรือมีทบอลไว้ด้านบน",
  "Grate the squash · Salt and wait": "ขูดสควอช · ใส่เกลือแล้วรอ",
  "Squeeze the squash · Sour cream mix": "บีบน้ำสควอช · ส่วนผสมซาวร์ครีม",
  "Soften the onion … Season": "ผัดหัวหอมให้นิ่ม … ปรุงรส",
  "with a fresh chili": "ใส่พริกสด",
  "Csipetke": "ชิเปตเก",
  "With csipetke": "ใส่ชิเปตเก",
  "pinched pasta": "แป้งชิ้นเล็กที่บิด้วยมือ",
  "Without csipetke": "ไม่ใส่ชิเปตเก",
  "Cut the beef": "หั่นเนื้อวัว",
  "Cut the beef into 1.5 cm cubes.": "หั่นเนื้อวัวเป็นลูกเต๋าขนาด 1.5 ซม.",
  "Cubed": "หั่นเต๋าแล้ว",
  "Chop the onion and garlic": "สับหัวหอมและกระเทียม",
  "Finely chop the onion; crush the garlic.": "สับหัวหอมให้ละเอียด บุบกระเทียม",
  "Melt the lard in the large pot and cook the onion until soft and golden.": "ละลายน้ำมันหมูในหม้อใหญ่ แล้วผัดหัวหอมจนนิ่มและเหลืองทอง",
  "Turn up the heat, add the beef and stir until it has lost its red colour all over.": "เร่งไฟ ใส่เนื้อวัวแล้วผัดจนไม่มีด้านไหนเป็นสีแดง",
  "No red left": "ไม่แดงแล้ว",
  "Paprika off the heat": "ปาปริกานอกเตา",
  "Pull the pot off the heat. Stir in the paprika, the crushed caraway and the garlic, then add a splash of water at once: paprika burns quickly and turns bitter.": "ยกหม้อลงจากเตา คนปาปริกา เมล็ดคาราเวย์บุบ และกระเทียม แล้วเติมน้ำเล็กน้อยทันที เพราะปาปริกาไหม้ง่ายและจะขม",
  "Red and fragrant": "แดงและหอม",
  "Stew the beef": "ตุ๋นเนื้อวัว",
  "Add the salt, the pepper and enough water to just cover the meat. Cover and simmer gently, adding a little water when it gets low.": "ใส่เกลือ พริกไทย และน้ำพอท่วมเนื้อ ปิดฝาแล้วตุ๋นไฟอ่อน ถ้าน้ำงวดให้เติมน้ำเล็กน้อย",
  "Beef nearly tender": "เนื้อเกือบนุ่ม",
